/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.state.isFilterLoading;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const {selectedFilterId, comparisonModel} = api.state;
  const {output} = api.data.analytics_cb_locale_get_list;

  if (!selectedFilterId && output) {
    if (comparisonModel && comparisonModel.length === 1 && !comparisonModel[0].field.internal) {
      return output['all'];
    } else {
      return output['custom'];
    }
  }
	return '';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        output
    } = api.data.get_filters_list_in_modal;
    const defaultFilterList = [];
    const savedFilterList = [];
    if (output) {
        output.forEach(filter => {
            if (filter.source === 'custom') {
                savedFilterList.push({
                    id: filter.id,
                    label: filter.label
                });
            } else {
                defaultFilterList.push({
                    id: filter.id,
                    label: filter.label
                });
            }
        });
    }

    return [{
        label: 'Default filters',
        children: defaultFilterList
    }, {
        label: 'Saved filters',
        children: savedFilterList
    }];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const filterId = api.state.selectedFilterId;
	return [filterId];
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const emptyComparisonItem = {...api.state.emptyComparisonItem};
	const {bucketName} = api.state;
	emptyComparisonItem.tableName = bucketName;
	return {
		propName: 'comparisonModel',
		value: [emptyComparisonItem]
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return api.state.isFilterLoading;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.state.isFilterSaving;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.state.filterSaveErrorMessage;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.state.filterNameInput;
}
